/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python - <<'PY'
from service import offset

for page in (1, 2, 4, 100, 10**20):
    for size in range(1, 101):
        assert offset(page, size) == (page - 1) * size

invalid = (-100, -1, 0, 1.0, 1.5, True, False, None, '1', [], {}, float('nan'), float('inf'))
for value in invalid:
    for args in ((value, 10), (1, value)):
        try:
            offset(*args)
        except ValueError:
            pass
        else:
            raise AssertionError(args)
for size in (101, 1000):
    try:
        offset(1, size)
    except ValueError:
        pass
    else:
        raise AssertionError(size)
print('Pagination boundary and validation checks passed.')
PY"

